def create_3x3_pattern(r, c):
    """Create a 3x3 pattern with 3s border and 2 center at (r,c)"""
    pattern = [[0]*3 for _ in range(3)]
    # Border of 3s
    for i in range(3):
        for j in range(3):
            if i == 0 or i == 2 or j == 0 or j == 2:  # border
                pattern[i][j] = 3
    # Center of 2
    pattern[1][1] = 2
    return pattern

height, width = 16, 18
output = [[0]*width for _ in range(height)]

# Fill 3x3 patterns at all 4 locations
pattern_positions = [(1, 1), (1, 9), (8, 1), (8, 9)]
for r, c in pattern_positions:
    for i in range(3):
        for j in range(3):
            output[r+i][c+j] = 3 if (i == 0 or i == 2 or j == 0 or j == 2) else 2

print("Completed 16x18 grid:\n")
for row in output:
    print(' '.join(map(str, row)))

